DESIGN_DOC = r'''# RNA-TR-Scout Stage 15B
## Memory-bounded package validator design v0.1.0

### Status

- Candidate status: **PROVISIONAL / NOT ACTIVE**
- Core schema: **v0.4.2 unchanged**
- Frozen package semantics: **unchanged within the Stage15A core equivalence scope**
- Full 5.31M execution: **not authorized by this stage**
- Locus aggregation: **NOT_RUN; biology-layer aggregation remains out of scope**

### Problem

The 500k prepublication parallel package validator reached approximately 26.6 GiB RSS. A naive 10.625392x projection is approximately 282.6 GiB, above the 125.6 GiB host RAM. The peak comes from loading complete TSV tables as Python `list[dict]` objects, with package and flank components overlapping in the parallel wrapper.

### Frozen semantic decomposition

The frozen v0.4.2 package validator consists of:

1. v0.4.0 core five-table validation;
2. v0.4.1 locus aggregation validation, which returns `NOT_RUN_PASS` when all three aggregate tables are absent;
3. v0.4.2 flank uniqueness validation.

For the current core package, every cross-table predicate is contained within one `evidence_id`-connected component, except the five global primary-key uniqueness predicates. Stage15A uses read-coherent shards, so every row belonging to one evidence component remains in the same shard.

The candidate therefore executes the exact frozen `rnatr_v042_validate_package.py` on every read-coherent shard and adds exact global uniqueness checks for:

- `read_evidence.evidence_id`
- `general_repeat_calls.caller_record_id`
- `repeat_events.repeat_event_id`
- `repeat_segments.repeat_call_id`
- `repeat_interruptions.interruption_id`

Global uniqueness uses GNU external sort with a fixed memory buffer. No probabilistic hash or Bloom-filter acceptance decision is used.

### Equivalence scope

The formal scope is:

`STAGE15A_READ_COHERENT_SHARDS_CORE_V042_NO_LOCUS_AGGREGATION`

Within this scope, the conjunction of exact frozen shard validation plus exact global primary-key uniqueness is equivalent to frozen global v0.4.2 core-package validation. Final-package/shard row-count parity, guarded merge implementation, package manifest, and atomic publication are execution-provenance gates kept separate from frozen semantic equivalence.

### Memory bound

With `W` concurrent shard validators:

`peak_RSS <= W * largest_single_shard_frozen_RSS + external_sort_buffer + orchestration_overhead`

The initial candidate uses three workers and a 512 MiB external-sort buffer. At full scale, one of 12 shards contains approximately 0.88545 of the current 500k global workload. The 500k equivalence run measures both global frozen RSS and per-shard RSS before selecting the full-scale worker count.

### Positive equivalence

Required:

- 100k final package: frozen PASS and candidate PASS
- 500k replicate A final package: frozen PASS and candidate PASS
- exact accept parity on a small positive fixture extracted from the 100k package

### Negative equivalence fixtures

Versioned fixtures cover:

- missing core artifact
- partial locus-aggregation package
- flank boolean/status inconsistency
- event coordinate-length inconsistency
- caller-to-evidence FK failure
- cross-shard duplicate `evidence_id`
- cross-shard duplicate `caller_record_id`
- cross-shard duplicate `repeat_event_id`
- cross-shard duplicate `repeat_call_id`
- cross-shard duplicate `interruption_id`

For each fixture, frozen and candidate acceptance must agree.

### Deliberate non-actions

This stage does not:

- modify active pipeline paths;
- modify SSOT;
- modify evidence schema v0.4.2;
- start the full 5.31M run;
- promote the candidate to ACTIVE;
- implement biology/interpretation aggregation.
'''


def progress(message: str) -> None:
    print(f"[Stage15B] {message}", flush=True)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def ensure_file(path: Path) -> None:
    if not path.is_file() or path.stat().st_size == 0:
        raise RuntimeError(f"missing or empty file: {path}")


def atomic_write(path: Path, data: bytes, mode: int | None = None) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name("." + path.name + ".part")
    with tmp.open("wb") as handle:
        handle.write(data)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)
    if mode is not None:
        path.chmod(mode)


def write_tsv(path: Path, fieldnames: list[str], rows: Iterable[dict[str, object]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name("." + path.name + ".part")
    with tmp.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, delimiter="\t", lineterminator="\n")
        writer.writeheader()
        for row in rows:
            writer.writerow(row)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def write_metrics(path: Path, rows: Iterable[tuple[str, object]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name("." + path.name + ".part")
    with tmp.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, delimiter="\t", lineterminator="\n")
        writer.writerow(["metric", "value"])
        writer.writerows(rows)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def read_metrics(path: Path) -> dict[str, str]:
    ensure_file(path)
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.reader(handle, delimiter="\t")
        header = next(reader, None)
        if header != ["metric", "value"]:
            raise RuntimeError(f"unexpected metric header: {path}: {header}")
        return {row[0]: row[1] for row in reader if len(row) >= 2}


def verify_guard_map(guards: dict[Path, str], label: str) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for path, expected in guards.items():
        ensure_file(path)
        observed = sha256_file(path)
        status = "PASS" if observed == expected else "FAIL"
        rows.append({
            "guard_class": label,
            "path": str(path),
            "expected_sha256": expected,
            "observed_sha256": observed,
            "status": status,
        })
        if status != "PASS":
            raise RuntimeError(f"{label} guard mismatch: {path}: {observed} != {expected}")
    return rows


def install_exact(path: Path, payload: bytes, expected_sha: str, mode: int | None = None) -> str:
    observed_payload = sha256_bytes(payload)
    if observed_payload != expected_sha:
        raise RuntimeError(f"embedded payload SHA mismatch: {observed_payload} != {expected_sha}")
    if path.exists():
        observed = sha256_file(path)
        if observed != expected_sha:
            raise RuntimeError(f"refusing to overwrite non-identical file: {path}: {observed}")
        if mode is not None:
            path.chmod(mode)
        return "REUSED_IDENTICAL"
    atomic_write(path, payload, mode=mode)
    if sha256_file(path) != expected_sha:
        raise RuntimeError(f"installed payload SHA mismatch: {path}")
    return "INSTALLED_NEW"


def parse_time_v(path: Path) -> dict[str, str]:
    values: dict[str, str] = {}
    if not path.is_file():
        return values
    for raw in path.read_text(encoding="utf-8", errors="replace").splitlines():
        text = raw.strip()
        if ":" not in text:
            continue
        key, value = text.rsplit(":", 1)
        values[key.strip()] = value.strip()
    return values


def run_timed(label: str, command: list[str], log_root: Path) -> dict[str, object]:
    run_dir = log_root / label
    run_dir.mkdir(parents=True, exist_ok=False)
    stdout_path = run_dir / "stdout.log"
    stderr_path = run_dir / "stderr.log"
    time_path = run_dir / "time_v.txt"
    started = time.perf_counter()
    proc = subprocess.run(
        ["/usr/bin/time", "-v", "-o", str(time_path), *command],
        text=True,
        capture_output=True,
    )
    elapsed = time.perf_counter() - started
    stdout_path.write_text(proc.stdout, encoding="utf-8")
    stderr_path.write_text(proc.stderr, encoding="utf-8")
    timing = parse_time_v(time_path)
    return {
        "label": label,
        "command": json.dumps(command, ensure_ascii=False),
        "elapsed_seconds": elapsed,
        "maximum_resident_set_kbytes": int(timing.get("Maximum resident set size (kbytes)", "0") or 0),
        "exit_code": proc.returncode,
        "accepted": proc.returncode == 0,
        "stdout_log": str(stdout_path),
        "stderr_log": str(stderr_path),
        "time_log": str(time_path),
        "stdout": proc.stdout,
        "stderr": proc.stderr,
    }


def open_tsv(path: Path):
    opener = gzip.open if path.suffix == ".gz" else open
    return opener(path, "rt", encoding="utf-8", newline="")


def read_headers(package: Path) -> dict[str, list[str]]:
    headers: dict[str, list[str]] = {}
    for table in CORE_TABLES:
        path = package / f"{table}.tsv"
        ensure_file(path)
        with path.open("r", encoding="utf-8", newline="") as handle:
            reader = csv.reader(handle, delimiter="\t")
            header = next(reader, None)
        if not header:
            raise RuntimeError(f"missing header: {path}")
        headers[table] = header
    return headers


def select_fixture_evidence_ids(package: Path) -> list[str]:
    values: list[str] = []
    for table in ("repeat_interruptions", "repeat_events"):
        with (package / f"{table}.tsv").open("r", encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle, delimiter="\t")
            for row in reader:
                eid = row["evidence_id"]
                if eid not in values:
                    values.append(eid)
                if len(values) >= 2:
                    return values[:2]
    raise RuntimeError("unable to select two called evidence groups for fixtures")


def extract_fixture_rows(package: Path, evidence_ids: list[str]) -> tuple[dict[str, list[str]], dict[int, dict[str, list[dict[str, str]]]]]:
    headers = read_headers(package)
    wanted = set(evidence_ids)
    by_shard: dict[int, dict[str, list[dict[str, str]]]] = {
        0: {table: [] for table in CORE_TABLES},
        1: {table: [] for table in CORE_TABLES},
    }
    index_by_eid = {evidence_ids[0]: 0, evidence_ids[1]: 1}
    for table in CORE_TABLES:
        with (package / f"{table}.tsv").open("r", encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle, delimiter="\t")
            for row in reader:
                eid = row.get("evidence_id")
                if eid in wanted:
                    by_shard[index_by_eid[eid]][table].append(dict(row))
    for shard in (0, 1):
        if len(by_shard[shard]["read_evidence"]) != 1:
            raise RuntimeError(f"fixture read_evidence group invalid for shard {shard}")
        for table in ("general_repeat_calls", "repeat_events", "repeat_segments", "repeat_interruptions"):
            if not by_shard[shard][table]:
                raise RuntimeError(f"fixture requires nonempty {table} in shard {shard}")
    return headers, by_shard


def row_sort_key(table: str, row: dict[str, str]):
    values: list[object] = []
    for field, numeric in KEY_FIELDS[table]:
        value = row[field]
        values.append(int(value) if numeric and value not in {"", "."} else (0 if numeric else value))
    return tuple(values)


def write_fixture(root: Path, headers: dict[str, list[str]], by_shard: dict[int, dict[str, list[dict[str, str]]]]) -> tuple[Path, Path]:
    final = root / "final_package"
    shards_root = root / "shards"
    final.mkdir(parents=True, exist_ok=False)
    for shard in (0, 1):
        package = shards_root / f"shard_{shard:03d}" / "package_plain"
        package.mkdir(parents=True, exist_ok=False)
        for table in CORE_TABLES:
            rows = sorted(by_shard[shard][table], key=lambda row, t=table: row_sort_key(t, row))
            write_tsv(package / f"{table}.tsv", headers[table], rows)
    for table in CORE_TABLES:
        rows = sorted(
            [dict(row) for shard in (0, 1) for row in by_shard[shard][table]],
            key=lambda row, t=table: row_sort_key(t, row),
        )
        write_tsv(final / f"{table}.tsv", headers[table], rows)
    return final, shards_root


def replace_equal(rows: list[dict[str, str]], field: str, old: str, new: str) -> None:
    for row in rows:
        if row.get(field) == old:
            row[field] = new


def mutate_fixture(case: str, by_shard: dict[int, dict[str, list[dict[str, str]]]]) -> None:
    s0 = by_shard[0]
    s1 = by_shard[1]
    if case == "FLANK_STATUS_BOOLEAN_MISMATCH":
        row = s0["read_evidence"][0]
        row["left_flank_uniqueness_status"] = "ASSESSED_UNIQUE"
        row["left_flank_unique"] = "false"
        return
    if case == "EVENT_COORDINATE_LENGTH_MISMATCH":
        row = s0["repeat_events"][0]
        row["repeat_bp_observed"] = str(int(row["repeat_bp_observed"]) + 1)
        return
    if case == "CALLER_EVIDENCE_FK_FAILURE":
        s0["general_repeat_calls"][0]["evidence_id"] = "NONEXISTENT_EVIDENCE_ID"
        return
    if case == "DUPLICATE_EVIDENCE_ID_CROSS_SHARD":
        old = s1["read_evidence"][0]["evidence_id"]
        new = s0["read_evidence"][0]["evidence_id"]
        for table in CORE_TABLES:
            replace_equal(s1[table], "evidence_id", old, new)
        return
    if case == "DUPLICATE_CALLER_RECORD_ID_CROSS_SHARD":
        old = s1["general_repeat_calls"][0]["caller_record_id"]
        new = s0["general_repeat_calls"][0]["caller_record_id"]
        replace_equal(s1["general_repeat_calls"], "caller_record_id", old, new)
        replace_equal(s1["read_evidence"], "best_caller_record_id", old, new)
        replace_equal(s1["repeat_events"], "primary_caller_record_id", old, new)
        replace_equal(s1["repeat_segments"], "caller_record_id", old, new)
        replace_equal(s1["repeat_interruptions"], "caller_record_id", old, new)
        return
    if case == "DUPLICATE_REPEAT_EVENT_ID_CROSS_SHARD":
        old = s1["repeat_events"][0]["repeat_event_id"]
        new = s0["repeat_events"][0]["repeat_event_id"]
        replace_equal(s1["repeat_events"], "repeat_event_id", old, new)
        replace_equal(s1["general_repeat_calls"], "repeat_event_id", old, new)
        replace_equal(s1["read_evidence"], "best_repeat_event_id", old, new)
        replace_equal(s1["repeat_segments"], "repeat_event_id", old, new)
        replace_equal(s1["repeat_interruptions"], "repeat_event_id", old, new)
        return
    if case == "DUPLICATE_REPEAT_CALL_ID_CROSS_SHARD":
        old = s1["repeat_segments"][0]["repeat_call_id"]
        new = s0["repeat_segments"][0]["repeat_call_id"]
        replace_equal(s1["repeat_segments"], "repeat_call_id", old, new)
        replace_equal(s1["general_repeat_calls"], "primary_repeat_call_id", old, new)
        replace_equal(s1["read_evidence"], "best_repeat_call_id", old, new)
        replace_equal(s1["repeat_events"], "primary_repeat_call_id", old, new)
        replace_equal(s1["repeat_interruptions"], "repeat_call_id", old, new)
        return
    if case == "DUPLICATE_INTERRUPTION_ID_CROSS_SHARD":
        old = s1["repeat_interruptions"][0]["interruption_id"]
        new = s0["repeat_interruptions"][0]["interruption_id"]
        replace_equal(s1["repeat_interruptions"], "interruption_id", old, new)
        return
    raise RuntimeError(f"unknown fixture mutation: {case}")


def run_fixture_suite(
    candidate: Path,
    log_root: Path,
    fixtures_root: Path,
) -> list[dict[str, object]]:
    evidence_ids = select_fixture_evidence_ids(PACKAGE_100K)
    headers, baseline_rows = extract_fixture_rows(PACKAGE_100K, evidence_ids)
    cases: list[tuple[str, bool, str | None]] = [
        ("POSITIVE_TWO_EVIDENCE_GROUPS", True, None),
        ("MISSING_READ_EVIDENCE", False, None),
        ("PARTIAL_LOCUS_AGGREGATION", False, None),
        ("FLANK_STATUS_BOOLEAN_MISMATCH", False, "FLANK_STATUS_BOOLEAN_MISMATCH"),
        ("EVENT_COORDINATE_LENGTH_MISMATCH", False, "EVENT_COORDINATE_LENGTH_MISMATCH"),
        ("CALLER_EVIDENCE_FK_FAILURE", False, "CALLER_EVIDENCE_FK_FAILURE"),
        ("DUPLICATE_EVIDENCE_ID_CROSS_SHARD", False, "DUPLICATE_EVIDENCE_ID_CROSS_SHARD"),
        ("DUPLICATE_CALLER_RECORD_ID_CROSS_SHARD", False, "DUPLICATE_CALLER_RECORD_ID_CROSS_SHARD"),
        ("DUPLICATE_REPEAT_EVENT_ID_CROSS_SHARD", False, "DUPLICATE_REPEAT_EVENT_ID_CROSS_SHARD"),
        ("DUPLICATE_REPEAT_CALL_ID_CROSS_SHARD", False, "DUPLICATE_REPEAT_CALL_ID_CROSS_SHARD"),
        ("DUPLICATE_INTERRUPTION_ID_CROSS_SHARD", False, "DUPLICATE_INTERRUPTION_ID_CROSS_SHARD"),
    ]
    results: list[dict[str, object]] = []
    for case, expected_accept, mutation in cases:
        progress(f"fixture equivalence: {case}")
        root = fixtures_root / case
        rows = copy.deepcopy(baseline_rows)
        if mutation is not None:
            mutate_fixture(mutation, rows)
        final, shards = write_fixture(root, headers, rows)
        if case == "MISSING_READ_EVIDENCE":
            (final / "read_evidence.tsv").unlink()
            for path in shards.glob("shard_*/package_plain/read_evidence.tsv"):
                path.unlink()
        elif case == "PARTIAL_LOCUS_AGGREGATION":
            payload = b"locus_distribution_id\tlocus_id\n"
            (final / "locus_repeat_distributions.tsv").write_bytes(payload)
            (shards / "shard_000/package_plain/locus_repeat_distributions.tsv").write_bytes(payload)

        frozen = run_timed(
            f"fixture_{case}_frozen",
            [sys.executable, str(FROZEN_PACKAGE_VALIDATOR), "--package-dir", str(final)],
            log_root,
        )
        candidate_out = root / "candidate_qc"
        cand = run_timed(
            f"fixture_{case}_candidate",
            [
                sys.executable, str(candidate),
                "--package-dir", str(final),
                "--shards-root", str(shards),
                "--schema-dir", str(SCHEMA_DIR),
                "--output-dir", str(candidate_out),
                "--workers", "2",
                "--expected-shards", "2",
                "--sort-buffer", "64M",
            ],
            log_root,
        )
        frozen_accept = bool(frozen["accepted"])
        candidate_accept = bool(cand["accepted"])
        parity = frozen_accept == candidate_accept
        expected_ok = frozen_accept == expected_accept and candidate_accept == expected_accept
        results.append({
            "fixture": case,
            "expected_accept": str(expected_accept).lower(),
            "frozen_exit_code": frozen["exit_code"],
            "frozen_accept": str(frozen_accept).lower(),
            "candidate_exit_code": cand["exit_code"],
            "candidate_accept": str(candidate_accept).lower(),
            "accept_reject_parity": str(parity).lower(),
            "expected_behavior_match": str(expected_ok).lower(),
            "status": "PASS" if parity and expected_ok else "FAIL",
            "fixture_root": str(root),
        })
    failures = [row["fixture"] for row in results if row["status"] != "PASS"]
    if failures:
        raise RuntimeError("negative-fixture equivalence failure: " + ",".join(map(str, failures)))
    return results


def verify_manifest_artifacts(package: Path) -> tuple[float, list[dict[str, object]]]:
    started = time.perf_counter()
    manifest_path = package / "package_manifest.tsv"
    ensure_file(manifest_path)
    with manifest_path.open("r", encoding="utf-8", newline="") as handle:
        manifest = list(csv.DictReader(handle, delimiter="\t"))
    rows: list[dict[str, object]] = []
    for record in manifest:
        artifact = record["artifact"]
        path = package / artifact
        ensure_file(path)
        observed = sha256_file(path)
        status = "PASS" if path.stat().st_size == int(record["bytes"]) and observed == record["sha256"] else "FAIL"
        rows.append({
            "artifact": artifact,
            "manifest_bytes": record["bytes"],
            "observed_bytes": path.stat().st_size,
            "manifest_sha256": record["sha256"],
            "observed_sha256": observed,
            "status": status,
        })
        if status != "PASS":
            raise RuntimeError(f"500k package manifest mismatch: {artifact}")
    return time.perf_counter() - started, rows


def memtotal_kb() -> int:
    with Path("/proc/meminfo").open("r", encoding="utf-8") as handle:
        for line in handle:
            if line.startswith("MemTotal:"):
                return int(line.split()[1])
    raise RuntimeError("MemTotal unavailable")


def disk_free_bytes(path: Path) -> int:
    return shutil.disk_usage(path).free


def make_bundle(source_root: Path, bundle: Path) -> tuple[str, Path]:
    with tarfile.open(bundle, "w:gz", format=tarfile.PAX_FORMAT) as tar:
        tar.add(source_root, arcname=source_root.name)
    digest = sha256_file(bundle)
    sidecar = Path(str(bundle) + ".sha256")
    sidecar.write_text(f"{digest}  {bundle.name}\n", encoding="utf-8")
    return digest, sidecar


def main() -> int:
    if PROJECT_ROOT != Path("/mnt/intelssd/rnatr_project"):
        raise SystemExit("unexpected project root")
    if QC_ROOT.exists() or WORK_ROOT.exists():
        raise SystemExit(f"refusing to overwrite prior Stage15B v0.1.0 output: {QC_ROOT} or {WORK_ROOT}")
    QC_ROOT.mkdir(parents=True)
    WORK_ROOT.mkdir(parents=True)
    logs = QC_ROOT / "logs"
    logs.mkdir()
    started = time.perf_counter()
    overall_metrics: list[tuple[str, object]] = [
        ("stage_version", VERSION),
        ("candidate_status", "PROVISIONAL_NOT_ACTIVE"),
        ("full_5_31m_run_started", "false"),
    ]
    try:
        progress("preflight paths and frozen guards")
        for required in (PACKAGE_100K, SHARDS_100K, PACKAGE_500K, SHARDS_500K, SCHEMA_DIR):
            if not required.exists():
                raise RuntimeError(f"required path missing: {required}")
        guard_rows = verify_guard_map(EXPECTED_GUARDS, "FROZEN_OR_SSOT")
        guard_rows.extend(verify_guard_map(ACTIVE_PATH_GUARDS, "ACTIVE_PATH"))
        write_tsv(QC_ROOT / "preflight_guards.tsv", list(guard_rows[0].keys()), guard_rows)
        before_guards = {path: sha256_file(path) for path in {**EXPECTED_GUARDS, **ACTIVE_PATH_GUARDS}}

        progress("install provisional candidate and design records")
        candidate_payload = base64.b64decode(CANDIDATE_B64.encode("ascii"), validate=True)
        candidate_install = install_exact(CANDIDATE_DEST, candidate_payload, CANDIDATE_SHA256, mode=0o755)
        doc_payload = DESIGN_DOC.encode("utf-8")
        doc_sha = sha256_bytes(doc_payload)
        doc_install = install_exact(DOC_DEST, doc_payload, doc_sha)
        script_payload = Path(__file__).read_bytes()
        script_sha = sha256_bytes(script_payload)
        script_install = install_exact(SCRIPT_ARCHIVE_DEST, script_payload, script_sha, mode=0o755)
        overall_metrics.extend([
            ("candidate_path", CANDIDATE_DEST),
            ("candidate_sha256", CANDIDATE_SHA256),
            ("candidate_installation", candidate_install),
            ("design_doc_path", DOC_DEST),
            ("design_doc_sha256", doc_sha),
            ("design_doc_installation", doc_install),
            ("driver_archive_path", SCRIPT_ARCHIVE_DEST),
            ("driver_archive_sha256", script_sha),
            ("driver_archive_installation", script_install),
        ])

        positive_results: list[dict[str, object]] = []
        progress("positive equivalence 100k: frozen global validator")
        frozen_100k = run_timed(
            "positive_100k_frozen_global",
            [sys.executable, str(FROZEN_PACKAGE_VALIDATOR), "--package-dir", str(PACKAGE_100K)],
            logs,
        )
        positive_results.append(frozen_100k)
        progress(f"100k frozen complete: {float(frozen_100k['elapsed_seconds']):.2f}s, RSS={int(frozen_100k['maximum_resident_set_kbytes'])/1024/1024:.2f} GiB")
        candidate_100k_out = QC_ROOT / "positive_100k_candidate"
        progress("positive equivalence 100k: memory-bounded candidate")
        candidate_100k = run_timed(
            "positive_100k_candidate_sharded",
            [
                sys.executable, str(CANDIDATE_DEST),
                "--package-dir", str(PACKAGE_100K),
                "--shards-root", str(SHARDS_100K),
                "--schema-dir", str(SCHEMA_DIR),
                "--output-dir", str(candidate_100k_out),
                "--workers", "3",
                "--expected-shards", "12",
                "--sort-buffer", "512M",
            ],
            logs,
        )
        positive_results.append(candidate_100k)
        progress(f"100k candidate complete: {float(candidate_100k['elapsed_seconds']):.2f}s, RSS={int(candidate_100k['maximum_resident_set_kbytes'])/1024/1024:.2f} GiB")

        progress("positive equivalence 500k: frozen global validator; expected high RSS but safe at 500k")
        frozen_500k = run_timed(
            "positive_500k_frozen_global",
            [sys.executable, str(FROZEN_PACKAGE_VALIDATOR), "--package-dir", str(PACKAGE_500K)],
            logs,
        )
        positive_results.append(frozen_500k)
        progress(f"500k frozen complete: {float(frozen_500k['elapsed_seconds']):.2f}s, RSS={int(frozen_500k['maximum_resident_set_kbytes'])/1024/1024:.2f} GiB")
        candidate_500k_out = QC_ROOT / "positive_500k_candidate"
        progress("positive equivalence 500k: memory-bounded candidate")
        candidate_500k = run_timed(
            "positive_500k_candidate_sharded",
            [
                sys.executable, str(CANDIDATE_DEST),
                "--package-dir", str(PACKAGE_500K),
                "--shards-root", str(SHARDS_500K),
                "--schema-dir", str(SCHEMA_DIR),
                "--output-dir", str(candidate_500k_out),
                "--workers", "3",
                "--expected-shards", "12",
                "--sort-buffer", "512M",
            ],
            logs,
        )
        positive_results.append(candidate_500k)
        progress(f"500k candidate complete: {float(candidate_500k['elapsed_seconds']):.2f}s, RSS={int(candidate_500k['maximum_resident_set_kbytes'])/1024/1024:.2f} GiB")

        positive_rows: list[dict[str, object]] = []
        for row in positive_results:
            label = str(row["label"])
            expected_marker = (
                "RNATR_STAGE15B_SHARDED_MEMORY_BOUNDED_PACKAGE_VALIDATION_PASS"
                if "candidate" in label else "RNATR_V042_PACKAGE_VALIDATION_PASS"
            )
            marker_present = expected_marker in str(row["stdout"])
            status = "PASS" if bool(row["accepted"]) and marker_present else "FAIL"
            positive_rows.append({
                "label": label,
                "elapsed_seconds": f"{float(row['elapsed_seconds']):.9f}",
                "maximum_resident_set_kbytes": row["maximum_resident_set_kbytes"],
                "exit_code": row["exit_code"],
                "accepted": str(row["accepted"]).lower(),
                "expected_marker": expected_marker,
                "marker_present": str(marker_present).lower(),
                "status": status,
                "stdout_log": row["stdout_log"],
                "stderr_log": row["stderr_log"],
                "time_log": row["time_log"],
            })
        write_tsv(QC_ROOT / "positive_equivalence.tsv", list(positive_rows[0].keys()), positive_rows)
        if any(row["status"] != "PASS" for row in positive_rows):
            raise RuntimeError("one or more positive validators failed")
        if bool(frozen_100k["accepted"]) != bool(candidate_100k["accepted"]):
            raise RuntimeError("100k accept parity failed")
        if bool(frozen_500k["accepted"]) != bool(candidate_500k["accepted"]):
            raise RuntimeError("500k accept parity failed")

        progress("versioned positive/negative fixture accept-reject equivalence")
        fixture_rows = run_fixture_suite(CANDIDATE_DEST, logs, WORK_ROOT / "fixtures")
        write_tsv(QC_ROOT / "negative_fixture_equivalence.tsv", list(fixture_rows[0].keys()), fixture_rows)

        progress("500k package-manifest integrity audit")
        artifact_seconds, artifact_rows = verify_manifest_artifacts(PACKAGE_500K)
        write_tsv(QC_ROOT / "package_manifest_integrity_500k.tsv", list(artifact_rows[0].keys()), artifact_rows)

        progress("full-scale memory/runtime/storage projection")
        candidate_qc = read_metrics(candidate_500k_out / "memory_bounded_validator.qc.tsv")
        max_current_shard_rss = int(candidate_qc["maximum_single_shard_rss_kbytes"])
        frozen_500k_rss = int(frozen_500k["maximum_resident_set_kbytes"])
        direct_full_shard_estimate = frozen_500k_rss * FULL_PER_SHARD_TO_500K_GLOBAL
        scaled_current_shard_estimate = max_current_shard_rss * SCALE_FACTOR
        existing_parallel_bound = EXISTING_PARALLEL_VALIDATOR_RSS_KB * FULL_PER_SHARD_TO_500K_GLOBAL
        base_single_shard_kb = max(direct_full_shard_estimate, scaled_current_shard_estimate, existing_parallel_bound)
        safety_factor = 1.25
        projected_single_shard_kb = base_single_shard_kb * safety_factor
        projected_workers = 3
        sort_buffer_kb = 512 * 1024
        orchestration_kb = 2 * 1024 * 1024
        projected_peak_kb = projected_single_shard_kb * projected_workers + sort_buffer_kb + orchestration_kb
        host_kb = memtotal_kb()
        memory_fraction = projected_peak_kb / host_kb
        memory_status = "PASS" if memory_fraction <= 0.75 else "REVIEW_REDUCE_WORKERS"

        candidate_500k_seconds = float(candidate_500k["elapsed_seconds"])
        replacement_validator_stage_seconds = max(candidate_500k_seconds, MAX_GENERIC_VALIDATOR_SECONDS)
        projected_500k_total = (
            EXISTING_500K_TOTAL_SECONDS - EXISTING_500K_VALIDATOR_STAGE_SECONDS
            + replacement_validator_stage_seconds
        )
        projected_full_minutes = projected_500k_total * SCALE_FACTOR / 60.0
        runtime_status = (
            "PASS_STRICT" if projected_full_minutes <= 60.0
            else "PASS_WITH_DOCUMENTED_TOLERANCE" if projected_full_minutes <= 62.0
            else "REVIEW_OPTIMIZATION_REQUIRED"
        )

        free_bytes = disk_free_bytes(PROJECT_ROOT)
        collector_required_bytes = int(250.066597 * 1_000_000_000)
        storage_status = "PASS" if free_bytes >= collector_required_bytes else "BLOCKED_STORAGE_REMEDIATION_REQUIRED"
        full_authorized = False

        projection_rows = [
            {"metric": "full_read_count", "value": FULL_READS},
            {"metric": "benchmark_read_count", "value": BENCHMARK_READS},
            {"metric": "scale_factor", "value": f"{SCALE_FACTOR:.9f}"},
            {"metric": "full_per_shard_to_500k_global_ratio", "value": f"{FULL_PER_SHARD_TO_500K_GLOBAL:.9f}"},
            {"metric": "candidate_500k_elapsed_seconds", "value": f"{candidate_500k_seconds:.9f}"},
            {"metric": "frozen_global_500k_rss_kbytes", "value": frozen_500k_rss},
            {"metric": "candidate_500k_max_single_shard_rss_kbytes", "value": max_current_shard_rss},
            {"metric": "direct_full_single_shard_rss_estimate_kbytes", "value": f"{direct_full_shard_estimate:.3f}"},
            {"metric": "scaled_current_shard_rss_estimate_kbytes", "value": f"{scaled_current_shard_estimate:.3f}"},
            {"metric": "existing_parallel_bound_single_shard_kbytes", "value": f"{existing_parallel_bound:.3f}"},
            {"metric": "rss_safety_factor", "value": safety_factor},
            {"metric": "projected_full_single_shard_rss_kbytes", "value": f"{projected_single_shard_kb:.3f}"},
            {"metric": "projected_workers", "value": projected_workers},
            {"metric": "projected_full_validator_peak_rss_kbytes", "value": f"{projected_peak_kb:.3f}"},
            {"metric": "host_memtotal_kbytes", "value": host_kb},
            {"metric": "projected_memory_fraction", "value": f"{memory_fraction:.6f}"},
            {"metric": "memory_readiness_status", "value": memory_status},
            {"metric": "replacement_validator_stage_500k_seconds", "value": f"{replacement_validator_stage_seconds:.9f}"},
            {"metric": "projected_full_bam_to_final_minutes", "value": f"{projected_full_minutes:.9f}"},
            {"metric": "runtime_readiness_status", "value": runtime_status},
            {"metric": "current_project_free_bytes", "value": free_bytes},
            {"metric": "collector_recommended_minimum_free_bytes", "value": collector_required_bytes},
            {"metric": "storage_readiness_status", "value": storage_status},
            {"metric": "full_empirical_run_authorized", "value": str(full_authorized).lower()},
        ]
        write_tsv(QC_ROOT / "fullscale_projection_after_candidate.tsv", ["metric", "value"], projection_rows)

        after_guards = {path: sha256_file(path) for path in before_guards}
        guard_unchanged = before_guards == after_guards
        architecture_rows = [
            {"check": "frozen_and_ssot_guards_unchanged", "status": "PASS" if guard_unchanged else "FAIL"},
            {"check": "active_pipeline_modified", "status": "PASS"},
            {"check": "core_schema_modified", "status": "PASS"},
            {"check": "candidate_promoted_active", "status": "PASS"},
            {"check": "full_5_31m_run_started", "status": "PASS"},
            {"check": "locus_aggregation_started", "status": "PASS"},
        ]
        write_tsv(QC_ROOT / "architecture_consistency_targeted_audit.tsv", ["check", "status"], architecture_rows)
        if not guard_unchanged:
            raise RuntimeError("guarded source changed during Stage15B")

        validator_equivalence = "PASS"
        next_gate = (
            "OPTIMIZE_MEMORY_BOUNDED_VALIDATOR_RUNTIME"
            if runtime_status == "REVIEW_OPTIMIZATION_REQUIRED"
            else "INTEGRATE_CANDIDATE_INTO_PROVISIONAL_FULLSCALE_RUNNER_AND_REMEDIATE_STORAGE"
        )
        elapsed = time.perf_counter() - started
        overall_metrics.extend([
            ("positive_100k_accept_parity", "PASS"),
            ("positive_500k_accept_parity", "PASS"),
            ("negative_fixture_accept_reject_parity", "PASS"),
            ("negative_fixture_count", len(fixture_rows) - 1),
            ("validator_equivalence_status", validator_equivalence),
            ("candidate_500k_elapsed_seconds", f"{candidate_500k_seconds:.9f}"),
            ("candidate_500k_max_single_shard_rss_kbytes", max_current_shard_rss),
            ("frozen_500k_global_rss_kbytes", frozen_500k_rss),
            ("memory_readiness_status", memory_status),
            ("runtime_readiness_status", runtime_status),
            ("projected_full_bam_to_final_minutes", f"{projected_full_minutes:.9f}"),
            ("storage_readiness_status", storage_status),
            ("package_manifest_integrity_500k", "PASS"),
            ("package_manifest_integrity_seconds", f"{artifact_seconds:.9f}"),
            ("active_pipeline_modified", "false"),
            ("ssot_modified", "false"),
            ("core_schema_modified", "false"),
            ("candidate_promoted_active", "false"),
            ("full_5_31m_run_started", "false"),
            ("full_empirical_run_authorized", "false"),
            ("audit_status", "PASS"),
            ("stage_status", "PASS"),
            ("next_gate", next_gate),
            ("elapsed_seconds", f"{elapsed:.9f}"),
        ])
        write_metrics(QC_ROOT / "stage15b_memory_bounded_validator.qc.tsv", overall_metrics)

        progress("assemble Stage15B audit bundle")
        manifest_rows: list[dict[str, object]] = []
        bundle_stage = QC_ROOT / "rnatr_stage15b_memory_bounded_validator_equivalence_v0.1.0"
        bundle_stage.mkdir()
        for source, relative in (
            (CANDIDATE_DEST, Path("sources") / CANDIDATE_DEST.name),
            (DOC_DEST, Path("docs") / DOC_DEST.name),
            (SCRIPT_ARCHIVE_DEST, Path("sources") / SCRIPT_ARCHIVE_DEST.name),
        ):
            target = bundle_stage / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, target)
        for source in sorted(QC_ROOT.iterdir()):
            if source.name == bundle_stage.name:
                continue
            target = bundle_stage / "qc" / source.name
            target.parent.mkdir(parents=True, exist_ok=True)
            if source.is_dir():
                shutil.copytree(source, target, symlinks=True)
            else:
                shutil.copy2(source, target)
        for path in sorted(bundle_stage.rglob("*")):
            if path.is_file():
                manifest_rows.append({
                    "path": str(path.relative_to(bundle_stage)),
                    "bytes": path.stat().st_size,
                    "sha256": sha256_file(path),
                })
        write_tsv(bundle_stage / "artifact_manifest.tsv", ["path", "bytes", "sha256"], manifest_rows)
        bundle = DOWNLOADS / "rnatr_stage15b_memory_bounded_validator_equivalence_v0.1.0.tar.gz"
        if bundle.exists() or Path(str(bundle) + ".sha256").exists():
            raise RuntimeError(f"refusing to overwrite output bundle: {bundle}")
        bundle_sha, sidecar = make_bundle(bundle_stage, bundle)

        print("===== RNA-TR-Scout Stage 15B memory-bounded validator =====")
        print(f"validator equivalence\t{validator_equivalence}")
        print(f"positive 100k\tPASS")
        print(f"positive 500k\tPASS")
        print(f"negative fixtures\tPASS\t{len(fixture_rows)-1}")
        print(f"candidate 500k seconds\t{candidate_500k_seconds:.6f}")
        print(f"candidate max single-shard RSS GiB\t{max_current_shard_rss/1024/1024:.3f}")
        print(f"projected full validator peak RSS GiB\t{projected_peak_kb/1024/1024:.3f}")
        print(f"memory readiness\t{memory_status}")
        print(f"projected full BAM-to-final minutes\t{projected_full_minutes:.6f}")
        print(f"runtime readiness\t{runtime_status}")
        print(f"storage readiness\t{storage_status}")
        print("full 5.31M authorized\tfalse")
        print(f"next gate\t{next_gate}")
        print(f"OUTPUT_BUNDLE\t{bundle}")
        print(f"OUTPUT_SHA_FILE\t{sidecar}")
        print(f"OUTPUT_SHA256\t{bundle_sha}")
        shutil.rmtree(WORK_ROOT)
        shutil.rmtree(bundle_stage)
        return 0
    except Exception as exc:
        elapsed = time.perf_counter() - started
        overall_metrics.extend([
            ("stage_status", "FAIL"),
            ("failure_type", type(exc).__name__),
            ("failure_message", str(exc)),
            ("active_pipeline_modified", "false"),
            ("ssot_modified", "false"),
            ("core_schema_modified", "false"),
            ("full_5_31m_run_started", "false"),
            ("full_empirical_run_authorized", "false"),
            ("elapsed_seconds", f"{elapsed:.9f}"),
        ])
        write_metrics(QC_ROOT / "stage15b_memory_bounded_validator.qc.tsv", overall_metrics)
        (QC_ROOT / "failure_traceback.log").write_text(traceback.format_exc(), encoding="utf-8")
        print(f"STAGE15B_FAIL\t{type(exc).__name__}\t{exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
